DROP TABLE IF EXISTS players;
CREATE TABLE players (player_id TEXT, name TEXT, url TEXT, club_id TEXT, club TEXT, country TEXT, comp TEXT, comp_name TEXT, tier INTEGER, position TEXT, nationality TEXT, age INTEGER, contract_until TEXT, contract_iso TEXT, market_value TEXT, mv_eur INTEGER, agent_status TEXT, agent_text TEXT, comp_ru TEXT, country_ru TEXT, flag TEXT, PRIMARY KEY (player_id));
